tool.command:

  ln -f -s ${input_sdf_path} ${input_sdf_path}_`echo $$`.${input_sdf_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

gnina_select_pose

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__pose__dq__:${properties.pose},__dq__ligand__dq__:${properties.ligand},__dq__sort_by__dq__:__dq__${properties.sort_by}__dq____cc____cc__'
  #end if

  #if str($input_sdf_path) != 'None':
    --input_sdf_path ${input_sdf_path}_`echo $$`.${input_sdf_path.ext}
  #end if


  --output_sdf_path $outname_output_sdf_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_sdf_path}_`echo $$`.${input_sdf_path.ext};


  if test -f $outname_output_sdf_path; then mv $outname_output_sdf_path $output_sdf_path; fi;
